  // ── 🥗 food — Sum's real diet data (oz0.3), GREEN-FIELD rebuild. not a dashboard — a pantry you OPERATE:
  //    icon cards with dot-grid fill (the pips ARE the bar), state-colored by freshness, sectioned. tap −/＋
  //    to eat from the pantry (empties → grocery → ozhunga reorder). tracked by container, macros done once. ──

  const FOOD_PROFILE_HTML = `
    <div class="sp-block">
      <div class="sp-head">🥗 food profile — wellness reads this · no repeat questions</div>
      <div class="sp-grid">
        <label>diet<select class="sp-in" data-k="diet">
          <option value="">— choose —</option>
          <option>omnivore</option><option>vegetarian</option><option>vegan</option>
          <option>pescatarian</option><option>keto</option><option>paleo</option>
          <option>halal</option><option>kosher</option><option>other</option>
        </select></label>
        <label>how often I like to eat<input type="text" class="sp-in" data-k="frequency" placeholder="2–3 big meals · no snacking"></label>
        <label class="sp-full">how much at a time<textarea class="sp-ta" data-k="portion" rows="2" placeholder="large portions · one plate rule"></textarea></label>
        <label class="sp-full">favorite foods (good)<textarea class="sp-ta" data-k="favorites_good" rows="2" placeholder="smoothies, grilled chicken, broccoli, pistachios"></textarea></label>
        <label class="sp-full">favorite foods (bad — comfort foods I lean on)<textarea class="sp-ta" data-k="favorites_bad" rows="2" placeholder="sandwiches, cheese, anything fast"></textarea></label>
        <label class="sp-full">treats I allow myself<textarea class="sp-ta" data-k="treats" rows="2" placeholder="grapes, dark chocolate, pistachios"></textarea></label>
        <label class="sp-full">temptations I'm trying to avoid<textarea class="sp-ta" data-k="temptations" rows="2" placeholder="late-night snacking, alcohol, soda"></textarea></label>
        <label class="sp-full">background (anything wellness should know without asking)<textarea class="sp-ta" data-k="background" rows="3" placeholder="high caloric need (3000+), cook in batches, no food allergies"></textarea></label>
      </div>
      <button class="sp-save">save profile</button>
      <div class="sp-msg"></div>
    </div>
    <div class="sp-divider"></div>`

  // ── the chart IS the memory — seed DASH_DATA.food from the localStorage mirror before we bind FOOD, so a
  //    reload restores what you logged (the food doc had NO persistence seed — the silent-loss bug). guarded. ──
  try { const j = localStorage.getItem('toto_food_plan'); if (j) { const p = JSON.parse(j); if (p && Array.isArray(p.meals) && Array.isArray(p.pantry)) window.DASH_DATA.food = p } } catch (_) {}
  const FOOD = window.DASH_DATA.food   // meals + pantry — see dashboards-data.js (seeded from toto_food_plan above)
  const FOOD_SECT = [['ready', '🍗 cooked & ready'], ['prepped', '🥗 prepped'], ['stocked', '📦 in stock'], ['buy', '🛒 grocery · buy']]
  window.CARD_BUILDERS.food = function buildFood() {
    const sum = ms => ms.reduce((a, m) => ({ kcal: a.kcal + (+m.kcal || 0), p: a.p + (+m.p || 0), f: a.f + (+m.f || 0), c: a.c + (+m.c || 0) }), { kcal: 0, p: 0, f: 0, c: 0 })
    const dShift = (s, n) => { const d = new Date(s + 'T12:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10) }
    const dFmt = s => { const d = new Date(s + 'T12:00:00'); return isNaN(d) ? s : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][d.getDay()] + ' ' + (d.getMonth() + 1) + '/' + d.getDate() }
    const latest = () => { const ds = [...new Set(FOOD.meals.map(m => m.d).filter(Boolean))].sort(); return ds[ds.length - 1] || '2026-03-26' }
    let logRange = 2, logEnd = latest()   // the Journal tab opens on the 2-day diary (left=yesterday · right=today)
    const TODAY = todayIso()                                      // the REAL today (so "today" jumps to now, not the last logged day)
    const isFuture = d => d > TODAY                               // days after today are PLANS, not logs — fill them ahead
    FOOD.meals.forEach((m, i) => { if (!m.id) m.id = 'm' + i })   // stable ids → editable per-meal notes
    const grp = sts => FOOD.pantry.filter(i => sts.includes(i.st))
    const dots = (ct, mx) => { const cap = Math.min(mx || 8, 10); let h = '<div class="fc-dots">'; for (let k = 0; k < cap; k++) h += `<div class="fc-dot${k < ct ? ' on' : ''}"></div>`; return h + '</div>' }
    const meal = m => `<div class="dash-meal-row${m.status === 'planned' ? ' planned' : ''}"><div class="dash-meal"><span class="dash-meal-when">${m.t}</span><span class="dash-meal-what">${m.n}</span><span class="dash-meal-kcal">${m.kcal || '—'}</span></div><div class="fc-mnote" contenteditable="true" spellcheck="false" data-note-id="${m.id}" data-ph="＋ note — mood · why · how you felt">${m.note || ''}</div></div>`
    const fcard = (i, eat) => {
      const cls = i.ct === 0 ? 'restock' : i.ct <= 1 ? 'aging' : (i.st === 'ready' ? 'fresh' : 'stock')
      const ctrl = eat
        ? `<button class="fc-eat" data-k="${i.k}">I'm eating this →</button>`
        : `<div class="fc-row"><button class="fc-btn" data-k="${i.k}" data-d="-1">−</button><span class="fc-ct${i.ct === 0 ? ' none' : ''}">${i.ct}</span><button class="fc-btn" data-k="${i.k}" data-d="1">＋</button></div>`
      return `<div class="fc ${cls}"><span class="fc-icon" contenteditable="true" spellcheck="false" data-k="${i.k}" title="tap to edit — emoji or your own 3-char emoticon">${i.icon}</span><div class="fc-name">${i.n}</div>${ctrl}<div class="fc-unit">${i.u || ''}</div>${dots(i.ct, i.mx)}<div class="fc-note" contenteditable="true" spellcheck="false" data-note-k="${i.k}" data-ph="＋ note">${i.note || ''}</div>${i.exp ? `<div class="fc-warn">⚠ ${i.exp} left</div>` : ''}</div>`
    }
    const fuel = (t, label) => { const kP = t.p * 4, kC = t.c * 4, kF = t.f * 9, s = (kP + kC + kF) || 1, w = x => Math.round(100 * x / s); return `<div class="fc-fuel"><div class="fc-fuel-top"><span>🔥 <b>${t.kcal.toLocaleString()}</b> <small>${label}</small></span><span>P${t.p} · F${t.f} · C${t.c}</span></div><div class="fc-fuel-bar"><span class="p" style="width:${w(kP)}%"></span><span class="c" style="width:${w(kC)}%"></span><span class="f" style="width:${w(kF)}%"></span></div><div class="fc-fuel-key"><span class="p">protein ${t.p}g · ${w(kP)}%</span><span class="c">carbs ${t.c}g · ${w(kC)}%</span><span class="f">fat ${t.f}g · ${w(kF)}%</span></div></div>` }
    // ＋add a manual item — sel adds a state picker (pantry), 'meal' adds a kcal field; everything else adds to its tab's state
    const addRow = (add, ph, sel, planning) => `<div class="fc-addrow"><input class="fc-in fc-in-n" placeholder="${ph}">${sel ? '<select class="fc-in fc-sel"><option value="stocked">needs prep</option><option value="ready">ready</option><option value="prepped">prepped</option><option value="buy">buy</option></select>' : ''}${add === 'meal' ? '<input class="fc-in fc-in-k" type="number" placeholder="kcal" min="0">' : ''}<button class="fc-add${planning ? ' plan' : ''}" data-add="${add}">＋ ${add === 'meal' ? (planning ? 'plan' : 'log') : 'add'}</button><input class="fc-in fc-in-note" placeholder="＋ a note — mood · why · how you felt before / after (optional)">${add === 'meal' ? `<div class="fc-mac"><span class="fc-mac-lbl">macros · g</span><input class="fc-in fc-in-m" data-m="p" type="number" min="0" placeholder="P"><input class="fc-in fc-in-m" data-m="f" type="number" min="0" placeholder="F"><input class="fc-in fc-in-m" data-m="c" type="number" min="0" placeholder="C"></div><div class="fc-serv-row"><span class="fc-mac-lbl">servings</span>${SERV.map(([k, ic, nm]) => `<label class="fc-serv-in" title="${nm}">${ic}<input class="fc-in fc-in-s" data-s="${k}" type="number" min="0" placeholder="0"></label>`).join('')}</div>` : ''}</div>`
    // ── osc/journal beans — a tab's data-viz goes in the green SCOPE, its operate surface in the leather BOOK.
    //    each tab returns oscBean(scope) + journalBean(operate). "diff journal and osc on each tab." ──
    const oscBean = (label, html) => `<div class="dash-sub dash-osc"><div class="dash-sub-head" data-sub="osc">${label}<span class="dash-sub-caret">▼</span></div><div class="dash-sub-body">${html}</div><div class="dash-sub-slider" data-sub="osc" title="drag to resize">⇕</div></div>`
    const journalBean = (label, html) => `<div class="dash-sub dash-journal-card"><div class="dash-sub-head" data-sub="journal"><img class="jrnl-ico" src="cards/dashboards/wellness-journal.png" alt=""> ${label}<span class="dash-sub-caret">▼</span></div><div class="dash-sub-body"><div class="journal-pages single"><div class="journal-page left">${html}</div></div></div><div class="dash-sub-slider" data-sub="journal" title="drag to resize">⇕</div></div>`
    // the OPEN book — two real pages (left/right page pngs). header sits above the spread; foot below it.
    const journalBean2 = (label, header, left, right, foot) => `<div class="dash-sub dash-journal-card"><div class="dash-sub-head" data-sub="journal"><img class="jrnl-ico" src="cards/dashboards/wellness-journal.png" alt=""> ${label}<span class="dash-sub-caret">▼</span></div><div class="dash-sub-body">${header || ''}<div class="journal-pages"><div class="journal-page left">${left}</div><div class="journal-page right">${right}</div></div>${foot || ''}</div><div class="dash-sub-slider" data-sub="journal" title="drag to resize">⇕</div></div>`
    // ── the tabs (views onto the one doc), ＋add on each ──
    // ── the CARD tabs (pantry · eat · prep · grocery) — osc = the cards (the picker: −/＋ · dot-grids) ·
    //    journal = the ＋ INPUT: snap it for the AI (the agents' ＋: 📸 cam · 🖥️ screen · 📎 file · 🔗 link) or type it. ──
    const ATT = OZ_SNAP_ROW   // the shared row (00-shared) — link removed 2026-08-17
    const stockInput = (addKey, ph, sel, blurb) => `<div class="fc-group-title">${blurb}</div>${ATT}${addRow(addKey, ph, sel)}`
    const pantryHTML = () => {
      const cards = FOOD_SECT.map(([st, title]) => { const its = FOOD.pantry.filter(i => i.st === st); return its.length ? `<div class="fc-group"><div class="fc-group-title">${title}</div><div class="fc-items">${its.map(i => fcard(i, false)).join('')}</div></div>` : '' }).join('') || `<div class="fc-empty">pantry's empty — stock it in the book →</div>`
      return oscBean('📦 your pantry · pick + adjust', cards) + journalBean('＋ stock it', stockInput('pantry', 'or just type an item', true, `＋ what'd you bring home? snap it — wellness reads the labels &amp; container sizes`))
    }
    const eatHTML = () => {
      const items = grp(['ready', 'prepped'])
      const cards = `<div class="fc-group-title">🍽 ready &amp; prepped · tap "I'm eating this" to remove</div><div class="fc-items">${items.length ? items.map(i => fcard(i, true)).join('') : '<div class="fc-empty">nothing prepped yet.</div>'}</div>`
      return oscBean('🍽 ready now · zero decisions', cards) + journalBean('＋ add ready', stockInput('ready', 'or type something ready to eat', false, '＋ add something ready — snap it or type it'))
    }
    const prepHTML = () => {
      const items = grp(['stocked'])
      const cards = `<div class="fc-group-title">🔪 needs prepping · cook + portion</div><div class="fc-items">${items.length ? items.map(i => fcard(i, false)).join('') : '<div class="fc-empty">nothing waiting to prep.</div>'}</div>`
      return oscBean('🔪 to prep', cards) + journalBean('＋ add to prep', stockInput('stocked', 'or type a raw / needs-prep item', false, '＋ snap it at prep — wellness reads labels + container sizes, does the macro math, pushes it to ready'))
    }
    const groceryHTML = () => {
      const items = grp(['buy', 'depleted'])
      const cards = `<div class="fc-group-title">🛒 need to buy</div><div class="fc-items">${items.length ? items.map(i => fcard(i, false)).join('') : '<div class="fc-empty">list is clear 🎉</div>'}</div><div class="fc-reorder">empty an item and it drops here → reorder from <b>ozhunga.com</b> <span class="food-soon">(store card · pending)</span></div>`
      // the journal = a simple shopping list — toggle-check each item off as you grab it
      const checklist = items.length ? `<div class="grocery-list">${items.map(i => `<label class="gl-item${i.checked ? ' gl-done' : ''}"><input type="checkbox" class="gl-check" data-k="${i.k}"${i.checked ? ' checked' : ''}><span class="gl-icon">${i.icon || '🛒'}</span><span class="gl-name">${esc(i.n)}</span></label>`).join('')}</div>` : `<div class="fc-empty">list is clear 🎉</div>`
      const journal = `<div class="fc-group-title">🛒 need to buy · check it off</div>${checklist}<button class="fc-jprint" data-jp="grocery">🖨 print list</button>${stockInput('buy', 'or type an item (e.g. avocado)', false, '＋ add to the list — snap a label or type it')}`
      return oscBean('🛒 the list', cards) + journalBean('🛒 shopping list', journal)
    }
    // ── the log's serving taxonomy — each meal carries sv:{fr,vg,cb,pr,al,sw} (food-group servings,
    //    not grams). week/month tally these by day + aggregate. macros (P/F/C) stay grams. ──
    const SERV = [['fr', '🍎', 'fruit'], ['vg', '🥦', 'veggies'], ['cb', '🍞', 'carbs'], ['pr', '🍗', 'protein'], ['al', '🍺', 'alcohol'], ['sw', '🍰', 'sweets']]
    const sumServ = ms => ms.reduce((a, m) => { const s = m.sv || {}; SERV.forEach(([k]) => a[k] = (a[k] || 0) + (+s[k] || 0)); return a }, {})
    const dayList = (a, b) => { const out = []; for (let d = a; d <= b; d = dShift(d, 1)) out.push(d); return out }
    const loggedDays = (a, b) => dayList(a, b).filter(d => FOOD.meals.some(m => m.d === d))
    // a day as a column (the 3-day view): header (name · kcal) over the day's meal list
    const dayColumn = d => {
      const ms = FOOD.meals.filter(m => m.d === d).sort((x, y) => (x.t > y.t ? 1 : -1)), s = sum(ms)
      return `<div class="fc-daycol"><div class="fc-daycol-h"><span>${dFmt(d)}</span><span class="k">${s.kcal ? s.kcal.toLocaleString() : '—'}</span></div>${ms.length ? ms.map(meal).join('') : '<div class="fc-empty">—</div>'}</div>`
    }
    // the meal-frequency list (week/month): identical meals collapsed → ×count + their total kcal
    const freqHTML = ms => {
      const m = {}; ms.forEach(x => { const g = m[x.n] || (m[x.n] = { n: x.n, ct: 0, kcal: 0 }); g.ct++; g.kcal += (+x.kcal || 0) })
      const rows = Object.values(m).sort((a, b) => b.ct - a.ct || b.kcal - a.kcal)
      return rows.length ? rows.map(g => `<div class="dash-meal"><span class="dash-meal-what">${g.n}</span><span class="fc-x">×${g.ct}</span><span class="dash-meal-kcal">${g.kcal.toLocaleString()}</span></div>`).join('') : '<div class="fc-empty">no meals logged.</div>'
    }
    // the breakdown table — kcal · macros (grams) · the six serving counts. dayRows ? per-day (week)
    //  : just the rolled-up total+avg (month, "aggregated"). avg is per LOGGED day (days with meals).
    const cell = v => `<td>${v ? (typeof v === 'number' && v % 1 ? v.toFixed(1) : v.toLocaleString()) : '<span class="z">·</span>'}</td>`
    const dataCells = (s, sv) => `${cell(s.kcal)}${cell(s.p)}${cell(s.f)}${cell(s.c)}${SERV.map(([k]) => cell(sv[k] || 0)).join('')}`
    const breakdown = (ms, dayRows, firstLabel) => {
      const head = `<tr><th class="d">${firstLabel}</th><th>kcal</th><th>P</th><th>F</th><th>C</th>${SERV.map(([k, ic, nm]) => `<th title="${nm} servings">${ic}</th>`).join('')}</tr>`
      const body = (dayRows || []).map(d => { const dm = FOOD.meals.filter(m => m.d === d); return `<tr><td class="d">${dFmt(d)}</td>${dataCells(sum(dm), sumServ(dm))}</tr>` }).join('')
      const tot = sum(ms), tsv = sumServ(ms), n = new Set(ms.map(m => m.d)).size || 1
      const avgS = { kcal: Math.round(tot.kcal / n), p: Math.round(tot.p / n), f: Math.round(tot.f / n), c: Math.round(tot.c / n) }
      const avgV = {}; SERV.forEach(([k]) => avgV[k] = +((tsv[k] || 0) / n).toFixed(1))
      const totRow = `<tr class="tot"><td class="d">total</td>${dataCells(tot, tsv)}</tr>`
      const avgRow = `<tr class="avg"><td class="d">avg / day</td>${dataCells(avgS, avgV)}</tr>`
      return `<div class="fc-tablewrap"><table class="fc-tbl"><thead>${head}</thead><tbody>${body}${totRow}${avgRow}</tbody></table></div><div class="fc-cap">avg is per day with meals (${n} ${n === 1 ? 'day' : 'days'}) · 🍎🥦🍞🍗🍺🍰 = food-group servings</div>`
    }
    // 📓 the Journal tab — osc = the WEEK (macros + by-day breakdown, prints by week) · journal = the 2-DAY
    //    diary (left=yesterday · right=today, ←/→/today moves the window, the week osc follows) + log input.
    const logHTML = () => {
      const future = isFuture(logEnd)
      const wkStart = dShift(logEnd, -6), wkMeals = FOOD.meals.filter(m => m.d >= wkStart && m.d <= logEnd)
      const oscInner = fuel(sum(wkMeals), 'this week · ' + dFmt(wkStart) + ' → ' + dFmt(logEnd))
        + `<div class="dash-block"><div class="dash-block-label">meals · most repeated</div>${freqHTML(wkMeals)}</div>`
        + `<div class="dash-block"><div class="dash-block-label">by day · macros + servings</div>${breakdown(wkMeals, loggedDays(wkStart, logEnd), 'this week')}</div>`
      const start2 = dShift(logEnd, -1)
      const nav = `<div class="fc-logctrl"><button class="fc-arrow" data-arrow="-1" title="back a day">←</button><div class="sw-weeklabel">${dFmt(start2)} → ${dFmt(logEnd)}</div><button class="fc-range fc-today-mid${logEnd === TODAY ? ' on-today' : ''}" data-today="1" title="jump to today">today</button><button class="fc-arrow" data-arrow="1" title="forward a day — plan ahead">→</button></div>`
      const banner = future
        ? `<div class="fc-planbanner">🔮 planning · <b>${dFmt(logEnd)}</b> hasn’t happened — fill it below</div>`
        : (logEnd !== TODAY ? `<div class="fc-planbanner past">📅 looking back · <b>${dFmt(logEnd)}</b></div>` : '')
      const foot = `<button class="fc-jprint" data-jp="week">🖨 print this week</button><div class="fc-group-title">＋ log a meal — snap the plate for the AI, or type it</div>${ATT}${addRow('meal', future ? 'plan a meal for ' + dFmt(logEnd) : 'meal name', false, future)}`
      return oscBean('🥗 the week', oscInner) + journalBean2('2-day diary', nav + banner, dayColumn(start2), dayColumn(logEnd), foot)
    }
    const TABS = [['pantry', '📦 Pantry'], ['eat', '🍽 Eat Now'], ['prep', '🔪 Prep'], ['log', '📓 Journal'], ['grocery', '🛒 Grocery'], ['recipe', '🍳 Recipe']]
    // 🍳 RECIPE — osc = a picker + the chosen recipe's macros (total + per serving); journal = the full method
    //    in step-tabs (🛒 store → 🔪 prep → 🌿 garnish → 🍽 serve), with how-many × what-size servings.
    const RECIPES = [
      { name: 'Caesar Salad + Chicken', servings: 2, size: 'large bowl', macros: { kcal: 1300, p: 92, f: 82, c: 48 },
        store: ['1 romaine head', '2 chicken breasts', 'parmesan (1 cup, shaved)', 'caesar dressing', 'croutons', '1 lemon'],
        prep: ['grill chicken ~6–7 min/side, rest 5 min, slice', 'wash + dry romaine, chop', 'shave the parmesan'],
        garnish: ['cracked black pepper', 'a lemon wedge', 'extra shaved parmesan'],
        serve: ['toss romaine with dressing', 'plate, fan the chicken on top', 'finish with croutons + parmesan'] },
      { name: 'Garlic Bread', role: 'side', servings: 2, size: 'slices', macros: { kcal: 420, p: 10, f: 22, c: 46 },
        store: ['½ baguette', 'butter', '3 garlic cloves', 'parsley'],
        prep: ['mince the garlic', 'soften butter, fold in garlic + chopped parsley'],
        garnish: ['extra parsley', 'flaky salt'],
        serve: ['spread thick, broil 3–4 min until golden'] },
      { name: 'Pork Chops + Greens', role: 'main', servings: 2, size: 'plate', macros: { kcal: 1100, p: 78, f: 70, c: 22 },
        store: ['2 thick pork chops', 'broccoli (1 head)', 'butter', 'garlic', 'salt + pepper'],
        prep: ['salt the chops, rest 20 min', 'steam the broccoli ~5 min', 'mince garlic'],
        garnish: ['a knob of garlic butter', 'flaky salt'],
        serve: ['sear chops 4 min/side to 145°F, rest', 'plate with the greens', 'spoon the pan butter over'] },
      { name: 'Roasted Sweet Potato', role: 'side', servings: 2, size: 'wedges', macros: { kcal: 360, p: 4, f: 9, c: 64 },
        store: ['2 sweet potatoes', 'olive oil', 'paprika', 'salt'],
        prep: ['cut into wedges', 'toss with oil + paprika + salt'],
        garnish: ['flaky salt'],
        serve: ['roast 425°F ~25 min, flip once'] },
    ]
    // 🍳 the RECIPE BOOK — two recipes that go together per spread (main + side). ←/→ flips spreads; the osc is
    //    the index (jump to any pairing) + the combined kcal. one step selector cooks the pair together.
    let recipePair = 0, recipeStep = 'store'
    const recipeHTML = () => {
      const pairs = Math.ceil(RECIPES.length / 2)
      recipePair = Math.max(0, Math.min(pairs - 1, recipePair))
      const a = RECIPES[recipePair * 2], b = RECIPES[recipePair * 2 + 1]
      const STEPS = [['store', '🛒 store'], ['prep', '🔪 prep'], ['garnish', '🌿 garnish'], ['serve', '🍽 serve']]
      const page = r => {
        if (!r) return '<div class="fc-empty">—</div>'
        const per = m => Math.round(m / (r.servings || 1))
        const steps = (r[recipeStep] || []).map(s => `<li>${esc(s)}</li>`).join('') || '<li>—</li>'
        return `<div class="recipe-head">${esc(r.name)}</div><div class="recipe-sub">${r.role || ''} · ${r.servings} × ${esc(r.size)} · ${r.macros.kcal} kcal · ${per(r.macros.kcal)}/serving</div><ol class="recipe-steps">${steps}</ol>`
      }
      const idx = Array.from({ length: pairs }, (_, i) => { const x = RECIPES[i * 2]; return `<button class="fc-range${i === recipePair ? ' on' : ''}" data-rpair="${i}">${esc((x && x.name.split(' + ')[0]) || ('spread ' + (i + 1)))}</button>` }).join('')
      const pairKcal = (a ? a.macros.kcal : 0) + (b ? b.macros.kcal : 0)
      const oscInner = `<div class="fc-ranges" style="flex-wrap:wrap;gap:5px">${idx}</div><div class="fc-fuel"><div class="fc-fuel-top"><span>🍳 <b>${esc(a ? a.name : '')}</b>${b ? ' + ' + esc(b.name) : ''}</span><span>🔥 ${pairKcal.toLocaleString()} kcal</span></div></div>`
      const stepTabs = `<div class="ftabs">${STEPS.map(([k, l]) => `<button class="ftab fc-rstep${k === recipeStep ? ' on' : ''}" data-rstep="${k}">${l}</button>`).join('')}</div>`
      const nav = `<div class="fc-logctrl"><button class="fc-arrow" data-rnav="-1" title="previous pairing">←</button><div class="sw-weeklabel">spread ${recipePair + 1} / ${pairs}</div><button class="fc-arrow" data-rnav="1" title="next pairing">→</button></div>`
      // the step tabs ride ON the page (a cream bar spanning the spread); nav is just the ←/→
      const book = `<div class="dash-sub dash-journal-card"><div class="dash-sub-head" data-sub="journal"><img class="jrnl-ico" src="cards/dashboards/wellness-journal.png" alt=""> the recipe book<span class="dash-sub-caret">▼</span></div><div class="dash-sub-body">${nav}<button class="fc-jprint" data-jp="recipe">🖨 print this recipe</button><div class="journal-pages"><div class="recipe-steptabs">${stepTabs}</div><div class="journal-page left">${page(a)}</div><div class="journal-page right">${page(b)}</div></div></div><div class="dash-sub-slider" data-sub="journal" title="drag to resize">⇕</div></div>`
      return oscBean('🍳 recipe index', oscInner) + book
    }
    const VIEW = { pantry: pantryHTML, eat: eatHTML, prep: prepHTML, log: logHTML, grocery: groceryHTML, recipe: recipeHTML }
    // the food doc lives in the sandbox — plan = expectation, log = reality, same file. wellness reads/writes it.
    let lastSynced = ''
    const sync = () => { try { window.SANDBOX = window.SANDBOX || {}; const data = JSON.stringify(FOOD, null, 2); window.SANDBOX['food-plan.json'] = { kind: 'doc', ext: 'json', mime: 'application/json', data }; lastSynced = data; try { localStorage.setItem('toto_food_plan', data) } catch (_) {} } catch (_) {} }   // mirror to localStorage → survives reload (the chart IS the memory)
    const foodGear = document.createElement('button')
    foodGear.className = 'dash-gear'; foodGear.type = 'button'; foodGear.innerHTML = (window.OZ_GEAR_SVG || '⚙')
    foodGear.title = 'food profile — wellness reads this so it never re-asks'
    const body = `
      <div class="sleep-rpt"><div class="sleep-rpt-title">🥗 Food · ${FOOD.day}</div><div class="sleep-rpt-sub">a pantry you operate · plan = expectation, log = reality, same doc · 📷 hands a pic to the wellness crystal to read</div></div>
      <div class="ftabs">${TABS.map(([k, l]) => `<button class="ftab" data-tab="${k}">${l}</button>`).join('')}</div>
      <div class="fview"></div>
      <button class="fc-snap">📷 snap a plate or a pint → opens wellness to read it</button>
      <input type="file" class="fc-snap-in" accept="image/*" hidden>`
    // (2026-08-17) the head was the 🥗 EMOJI, which at card size read like art and wasn't. DRAWN now —
    //   Sum's call: the svg, not the gen'd png. (draw = svg · gen = png. they are different instructions.)
    //   the CARD is the salad, the DRAWER/deck tile stays the apple — Sum: "health diet varies".
    const el = dashCard('food', 'cards/wellness/food-salad.svg', 'FOOD', body, { badge: 'real · Mar 2026', live: true, lav: true, badgeTitle: "Sum's real oz0.3 food log (Mar 25–31) · operates now, AI sync pending", gear: foodGear })
    el.querySelector('.card-body').style.height = '560px'
    const view = el.querySelector('.fview')
    let tab = 'pantry'
    // the osc/journal sub-cards (on tabs that use the beans) — collapse + resize, re-applied each render
    const foodSubOpen = { osc: false, journal: true }, foodSubHeight = { osc: 280, journal: 340 }   // (Sum 2026-07-10) journal first · click the recipe/scope head for the readout
    const foodApplySubs = () => view.querySelectorAll('.dash-sub').forEach(s => {
      const k = s.classList.contains('dash-osc') ? 'osc' : 'journal'
      s.classList.toggle('collapsed', !foodSubOpen[k])
      const b = s.querySelector('.dash-sub-body'); if (!b) return
      if (k === 'osc') { b.style.minHeight = ''; b.style.height = foodSubHeight.osc + 'px' } else { b.style.height = 'auto'; b.style.minHeight = foodSubHeight.journal + 'px' }
    })
    const render = t => { tab = t || tab; view.innerHTML = (VIEW[tab] || pantryHTML)(); el.querySelectorAll('.ftab').forEach(b => b.classList.toggle('on', b.dataset.tab === tab)); foodApplySubs(); sync() }
    el.querySelector('.ftabs').addEventListener('click', e => { const b = e.target.closest('.ftab'); if (b) { e.stopPropagation(); render(b.dataset.tab) } })
    // the pantry's ＋ → the wellness agent's attach engine (📸 cam · 🖥️ screen · 📎 file · 🔗 link) — snap groceries for the AI
    const toWellness = act => ozSnapTo('wellness', act)   // the shared router (00-shared)
    // the grocery shopping-list checkboxes — toggle an item off (no re-render, keeps your place)
    view.addEventListener('change', e => { const ck = e.target.closest('.gl-check'); if (!ck) return; const it = FOOD.pantry.find(x => x.k === ck.dataset.k); if (it) { it.checked = ck.checked; const row = ck.closest('.gl-item'); if (row) row.classList.toggle('gl-done', ck.checked); sync() } })
    view.addEventListener('mousedown', e => {   // drag a sub-card's ⇕ slider (osc = height · journal = floor)
      const sl = e.target.closest('.dash-sub-slider'); if (!sl) return
      e.preventDefault(); e.stopPropagation()
      const k = sl.dataset.sub, b = sl.parentElement.querySelector('.dash-sub-body'); if (!b) return
      const sy = e.clientY, sh = b.offsetHeight; document.body.classList.add('resizing')
      const move = ev => { const h = Math.max(80, sh + ev.clientY - sy); if (k === 'osc') b.style.height = h + 'px'; else b.style.minHeight = h + 'px'; foodSubHeight[k] = h }
      const up = () => { document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); document.body.classList.remove('resizing') }
      document.addEventListener('mousemove', move); document.addEventListener('mouseup', up)
    })
    // 🖨 the PRINT bean on food — the week's nutrition as a clinician report (Sum's session-prep format)
    function printFood() {
      const end = latest(), start = dShift(end, -6)
      const win = FOOD.meals.filter(m => m.d >= start && m.d <= end)
      const dayList2 = []; for (let d = start; d <= end; d = dShift(d, 1)) dayList2.push(d)
      const dayCount = new Set(win.map(m => m.d)).size || 1
      const t = sum(win), sv = sumServ(win), range = dFmt(start) + ' → ' + dFmt(end)
      const rows = dayList2.map(d => {
        const dm = FOOD.meals.filter(m => m.d === d), ds = sum(dm)
        const meals = dm.length ? dm.map(m => `${esc(m.n)} &middot; ${m.kcal || 0} kcal${m.status === 'planned' ? ' (planned)' : ''}`).join('<br>') : '<span class="z">—</span>'
        return `<tr><td class="d">${dFmt(d)}</td><td class="n">${ds.kcal || 0}</td><td class="n">${ds.p || 0}/${ds.f || 0}/${ds.c || 0}</td><td>${meals}</td></tr>`
      }).join('')
      const grocery = FOOD.pantry.filter(i => i.st === 'buy' || i.ct === 0).map(i => esc(i.n)).join(', ') || 'nothing flagged'
      const servLine = SERV.map(([k, ic, nm]) => `${ic} ${nm} ${sv[k] || 0}`).join(' &middot; ')
      const now = new Date().toLocaleDateString()
      const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Nutrition Report · ${range}</title><style>${REPORT_CSS}</style></head><body>
        <h1>Nutrition Report &mdash; ${range} 🥗</h1>
        <div class="subtitle">Sum Bhodi  |  Food log &middot; macros + servings  &middot;  generated ${now}</div>
        <hr>
        <table class="scope">
          <tr><th>THIS WEEK &mdash; Nutrition Summary</th><th class="t">Value</th></tr>
          <tr><td>Average calories / day</td><td class="t">${Math.round(t.kcal / dayCount)} kcal${FOOD.goal ? ' (goal ' + FOOD.goal + ')' : ''}</td></tr>
          <tr><td>Avg protein / fat / carbs per day</td><td class="t">${Math.round(t.p / dayCount)} / ${Math.round(t.f / dayCount)} / ${Math.round(t.c / dayCount)} g</td></tr>
          <tr><td>Meals logged</td><td class="t">${win.length}</td></tr>
          <tr><td>Days with a log</td><td class="t">${dayCount} / 7</td></tr>
        </table>
        <h2>📊 What the numbers mean</h2>
        <ul>
          <li><b>Calories &amp; macros &mdash;</b> energy + protein / fat / carbs, from a photo of the plate (estimated, flagged as a guess) or logged by hand.</li>
          <li><b>Servings this week &mdash;</b> ${servLine}.</li>
        </ul>
        <h2>📅 Day by day</h2>
        <table class="days"><thead><tr><th>Day</th><th style="text-align:right">kcal</th><th style="text-align:right">P/F/C</th><th>Meals</th></tr></thead><tbody>${rows}</tbody></table>
        <h2>🛒 Grocery / running low</h2>
        <p>${grocery}</p>
        <div class="foot">Prepared with toto &middot; food estimated from photos is flagged as a guess, never fact.<br>This report covers <b>${range}</b>. Pair with the activity + sleep reports for the full picture.</div>
      </body></html>`
      wellnessPrint(html)
    }
    // (no top-bar print on the sub-cards — printing lives in each card's JOURNAL; the 🧘 wellness top bar
    //  carries the one master print. printFood() stays — the journal's "print this week" button calls it.)
    // per-journal prints (grocery list · the recipe spread) — share the print bean
    function printGrocery() {
      const items = grp(['buy', 'depleted'])
      const rows = items.map(i => `<li>${esc(i.n)}${i.checked ? ' &nbsp;✓ got it' : ''}</li>`).join('') || '<li>list is clear 🎉</li>'
      wellnessPrint(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Grocery List</title><style>${REPORT_CSS}</style></head><body><h1>🛒 Grocery List</h1><div class="subtitle">generated ${new Date().toLocaleDateString()}</div><hr><ul style="font-size:15px;line-height:2">${rows}</ul></body></html>`)
    }
    function printRecipe() {
      const sec = (t, arr) => `<h2>${t}</h2><ol>${(arr || []).map(s => `<li>${esc(s)}</li>`).join('')}</ol>`
      const one = r => { if (!r) return ''; const per = m => Math.round(m / (r.servings || 1)); return `<h1>${esc(r.name)}</h1><div class="subtitle">${r.role || ''} · ${r.servings} × ${esc(r.size)} · ${r.macros.kcal} kcal total · ${per(r.macros.kcal)}/serving · P${r.macros.p} F${r.macros.f} C${r.macros.c}</div><hr>${sec('🛒 store list', r.store)}${sec('🔪 prep', r.prep)}${sec('🌿 garnish', r.garnish)}${sec('🍽 serve', r.serve)}` }
      const a = RECIPES[recipePair * 2], b = RECIPES[recipePair * 2 + 1]
      wellnessPrint(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Recipe</title><style>${REPORT_CSS} h2{font-size:14px;margin:14px 0 4px} ol{padding-left:20px;line-height:1.6}</style></head><body>${one(a)}${b ? '<div style="page-break-before:always"></div>' + one(b) : ''}</body></html>`)
    }
    // manual ops everywhere: −/＋ adjust · "I'm eating this" decrements · ＋add into any category · log range/arrows
    view.addEventListener('click', e => {
      const subHead = e.target.closest('.dash-sub-head'); if (subHead) { e.stopPropagation(); const cs = subHead.parentElement; (subHead.closest('.card-body') || document).querySelectorAll('.dash-sub').forEach(s => s.classList.toggle('collapsed', s !== cs)); const k = subHead.dataset.sub; foodSubOpen.osc = (k === 'osc'); foodSubOpen.journal = (k === 'journal'); return }   // one sub at a time (scope/recipe OR journal)
      const rpair = e.target.closest('[data-rpair]'); if (rpair) { e.stopPropagation(); recipePair = +rpair.dataset.rpair; render('recipe'); return }
      const rnav = e.target.closest('[data-rnav]'); if (rnav) { e.stopPropagation(); recipePair += +rnav.dataset.rnav; render('recipe'); return }
      const rstep = e.target.closest('.fc-rstep'); if (rstep) { e.stopPropagation(); recipeStep = rstep.dataset.rstep; render('recipe'); return }
      const att = e.target.closest('.fc-att'); if (att) { e.stopPropagation(); toWellness(att.dataset.att); return }   // pantry ＋ → wellness reads the pic
      const jp = e.target.closest('.fc-jprint'); if (jp) { e.stopPropagation(); const k = jp.dataset.jp; if (k === 'grocery') printGrocery(); else if (k === 'recipe') printRecipe(); else printFood(); return }
      const tdy = e.target.closest('[data-today]'); if (tdy) { e.stopPropagation(); logEnd = TODAY; render(); return }   // jump to today in any view
      const rng = e.target.closest('.fc-range[data-range]'); if (rng) { e.stopPropagation(); logRange = +rng.dataset.range; render(); return }
      const arr = e.target.closest('.fc-arrow'); if (arr) { e.stopPropagation(); logEnd = dShift(logEnd, (+arr.dataset.arrow)); render(); return }   // no clamp — slide into the future to plan
      const btn = e.target.closest('.fc-btn, .fc-eat, .fc-add'); if (!btn) return; e.stopPropagation()
      if (btn.classList.contains('fc-btn')) {
        const it = FOOD.pantry.find(x => x.k === btn.dataset.k); if (!it) return
        it.ct = Math.max(0, Math.min(it.mx, it.ct + (+btn.dataset.d)))
        if (it.ct === 0 && it.st !== 'buy') { it._was = it.st; it.st = 'buy' } else if (it.ct > 0 && it.st === 'buy') it.st = it._was || 'stocked'
      } else if (btn.classList.contains('fc-eat')) {
        const it = FOOD.pantry.find(x => x.k === btn.dataset.k); if (it && it.ct > 0) { it.ct--; if (it.ct === 0) { it._was = it.st; it.st = 'buy' } }
      } else if (btn.classList.contains('fc-add')) {
        const add = btn.dataset.add, n = view.querySelector('.fc-in-n'), nt = view.querySelector('.fc-in-note'), note = (nt && nt.value.trim()) || ''
        if (add === 'meal') { const k = view.querySelector('.fc-in-k'); if (n && n.value.trim()) { const gm = m => { const i = view.querySelector('.fc-in-m[data-m="' + m + '"]'); return i ? +i.value || 0 : 0 }; const sv = {}; SERV.forEach(([sk]) => { const i = view.querySelector('.fc-in-s[data-s="' + sk + '"]'); const v = i ? +i.value || 0 : 0; if (v) sv[sk] = v }); FOOD.meals.push({ id: 'm' + Date.now(), d: logEnd, t: 'now', n: n.value.trim(), kcal: +k.value || 0, p: gm('p'), f: gm('f'), c: gm('c'), sv, status: isFuture(logEnd) ? 'planned' : 'eaten', note }) } }
        else if (n && n.value.trim()) { const sel = view.querySelector('.fc-sel'); const st = add === 'pantry' ? (sel ? sel.value : 'stocked') : add; const ic = { ready: '🍽', prepped: '🥗', stocked: '🥦', buy: '🛒' }[st] || '🍴'; FOOD.pantry.push({ k: 'x' + Date.now(), icon: ic, n: n.value.trim(), u: '', ct: st === 'buy' ? 0 : 1, mx: 4, st, note }) }
      }
      render()
    })
    // editable icons — tap a card's emoji, type your own (emoji or a 3-char emoticon). cap at 3 · Enter blurs.
    view.addEventListener('keydown', e => { const ed = e.target.closest('.fc-icon[contenteditable], .fc-note[contenteditable], .fc-mnote[contenteditable]'); if (ed && e.key === 'Enter') { e.preventDefault(); ed.blur() } })
    view.addEventListener('input', e => { const ic = e.target.closest('.fc-icon[contenteditable]'); if (!ic) return; const c = [...ic.textContent]; if (c.length > 3) { ic.textContent = c.slice(0, 3).join(''); const r = document.createRange(); r.selectNodeContents(ic); r.collapse(false); const s = getSelection(); s.removeAllRanges(); s.addRange(r) } })
    view.addEventListener('focusout', e => {
      // notes (pantry items by k · meals by id) — save the free text, no re-render (keeps the cursor)
      const nt = e.target.closest('.fc-note[contenteditable], .fc-mnote[contenteditable]')
      if (nt) { const txt = nt.textContent.trim(); if (nt.dataset.noteK) { const it = FOOD.pantry.find(x => x.k === nt.dataset.noteK); if (it) it.note = txt } else if (nt.dataset.noteId) { const m = FOOD.meals.find(x => x.id === nt.dataset.noteId); if (m) m.note = txt } sync(); return }
      const ic = e.target.closest('.fc-icon[contenteditable]'); if (!ic) return; const it = FOOD.pantry.find(x => x.k === ic.dataset.k); if (!it) return; it.icon = [...ic.textContent.trim()].slice(0, 3).join('') || it.icon; ic.textContent = it.icon; sync()
    })

    // 📷 → cache the pic + open the wellness crystal + hand it the image (BYOK vision reads it; no local model, no server)
    const snap = el.querySelector('.fc-snap'), snapIn = el.querySelector('.fc-snap-in')
    snap.addEventListener('click', e => { e.stopPropagation(); snapIn.click() })
    snapIn.addEventListener('change', () => {
      const f = snapIn.files[0]; snapIn.value = ''; if (!f) return
      if (window.toggleAgent) window.toggleAgent('wellness', true)
      setTimeout(() => { const bar = document.querySelector('.agent-bar.agent-wellness'); if (bar && window.attachFile) window.attachFile(bar, f) }, 90)
      snap.textContent = '✓ handed to wellness — it’ll read it and ask before touching your log'
      setTimeout(() => { snap.textContent = '📷 snap a plate or a pint → opens wellness to read it' }, 5000)
    })
    render('pantry')

    // ── watch the doc for EXTERNAL writes (wellness's edit_food_doc) → reload FOOD + re-render. our own
    //    sync()s are remembered (lastSynced) so the card never fights itself. closes photo→read→edit→card. ──
    const foodToast = msg => {
      let t = document.getElementById('fc-toast')
      if (!t) { t = document.createElement('div'); t.id = 'fc-toast'; t.className = 'fc-toast'; document.body.appendChild(t) }
      t.textContent = msg; t.classList.add('on'); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('on'), 3200)
    }
    const applyExternal = () => {
      const doc = window.SANDBOX && window.SANDBOX['food-plan.json']
      if (!doc || typeof doc.data !== 'string' || doc.data === lastSynced) return
      let next; try { next = JSON.parse(doc.data) } catch (_) { return }
      if (!next || !Array.isArray(next.meals) || !Array.isArray(next.pantry)) return
      if (next.day != null) FOOD.day = next.day
      if (next.goal != null) FOOD.goal = next.goal
      FOOD.meals = next.meals; FOOD.pantry = next.pantry
      lastSynced = doc.data
      try { localStorage.setItem('toto_food_plan', doc.data) } catch (_) {}   // an external (wellness) edit persists too
      render()                                  // re-render the open tab off the new state (re-syncs — harmless)
      foodToast('🔮 wellness updated your log')   // glass-box: you watch the AI's edit land, no refresh
    }
    clearInterval(window._foodWatch)
    window._foodWatch = setInterval(() => { if (!document.body.contains(el)) { clearInterval(window._foodWatch); return } applyExternal() }, 1200)

    // ── food profile: ⚙️ gear panel (same pattern as sleep profile) ──
    const FP_KEY = 'toto_food_profile'
    const foodPanel = document.createElement('div'); foodPanel.className = 'sleep-setup'; foodPanel.hidden = true
    foodPanel.innerHTML = `<div class="sleep-setup-head">⚙️ food settings</div>` + FOOD_PROFILE_HTML + dataInMini('food') + `<div class="ls-close-row"><button class="ls-close food-setup-x">✕ close settings</button></div>`
    el.querySelector('.card-body').appendChild(foodPanel)   // into the BODY → head + ⚙️ gear stay visible (gear toggles)
    // GLOBAL settings rule: settings OR content. opening hides the card's data; ✕ at the bottom (or the gear) brings it back.
    const fpSetOpen = on => { const cb = el.querySelector('.card-body'); [...cb.children].forEach(n => { if (n !== foodPanel) { n.hidden = on; n.style.display = on ? 'none' : '' } }); foodPanel.hidden = !on; if (on) el.classList.remove('collapsed'); cb.style.height = on ? 'auto' : '560px'; cb.style.overflow = on ? 'visible' : ''; if (on) fpLoad() }
    const fpFields = () => foodPanel.querySelectorAll('[data-k]')
    const fpLoad = () => {
      try {
        const p = JSON.parse(localStorage.getItem(FP_KEY) || '{}')
        fpFields().forEach(f => { if (p[f.dataset.k] != null) f.value = p[f.dataset.k] })
      } catch (_) {}
    }
    const fpSave = () => {
      const p = {}; fpFields().forEach(f => { if (f.value && f.value.trim()) p[f.dataset.k] = f.value.trim() })
      localStorage.setItem(FP_KEY, JSON.stringify(p))
      const m = foodPanel.querySelector('.sp-msg'); if (m) { m.textContent = '✓ saved'; setTimeout(() => { m.textContent = '' }, 1800) }
    }
    // the Samsung .zip road — same archive as sleep and exercise (Sum: "trace the path you used for fitness")
    const fdFile = document.createElement('input'); fdFile.type = 'file'; fdFile.accept = '.zip'; fdFile.hidden = true; foodPanel.appendChild(fdFile)
    fdFile.addEventListener('change', async () => {
      const f = fdFile.files && fdFile.files[0]; if (!f) return
      const msg = foodPanel.querySelector('.ozin-msg'); if (msg) msg.textContent = 'reading the zip…'
      try { const n = await window.importSamsungFood(f)
        if (msg) msg.textContent = `✓ ${n} meal${n === 1 ? '' : 's'} logged — reopen the card to see them`
        try { const j = localStorage.getItem('toto_food_plan'); if (j) window.DASH_DATA.food = JSON.parse(j) } catch (_) {}
        render()
      } catch (err) { if (msg) msg.textContent = '✕ ' + ((err && err.message) || err) }
      fdFile.value = ''
    })
    foodPanel.addEventListener('click', e => {
      if (e.target.closest('.ozin-imp')) { e.stopPropagation(); fdFile.click(); return }
      e.stopPropagation()
      if (e.target.closest('.food-setup-x')) { fpSetOpen(false); return }
      if (e.target.closest('.sp-save')) { e.stopPropagation(); fpSave() }
    })
    foodGear.addEventListener('click', e => { e.stopPropagation(); fpSetOpen(foodPanel.hidden) })

    return el
  }

